      lbl(S, 'l2', 19.0, 3.2, ['개발 모드에서는 스타일을 얼려, 바꾸려 해도 padding이 8로 남았어요', 'in development it froze each style, so padding stayed 8 when changed'], 'w', 2, { w: 12.4 });
