    code: ['// 60 fps -> 16.7 ms per frame', 'items.map(vm)   // 5 fields per row, 100k', '// hermes 0.12  0.74 µs/row  22,567 per frame', '// node V8      0.36 µs/row  46,388 per frame', 'JSON.parse 2.1 MB: 32 ms on hermes 0.12'],
    hl: [[4, 1, 'warn'], [0, 1, 'danger'], [1, 3, 'accent'], null],
    draw: (S) => {
      rbars(S, 'b1', .5, [['1 frame', .32, 'ok', '16.7 ms'], ['JSON 2.1MB', .61, 'warn', '32 ms'], ['100k rows', 1.41, 'warn', '74 ms'], ['sort 200k', 5.0, 'danger', '262 ms']], 1);
      lbl(S, 'l1', 19.0, 2.9, ['Hermes 0.12에서 2.1MB JSON.parse는 32ms로 두 프레임 가까이 걸렸어요', 'on Hermes 0.12, JSON.parse of 2.1 MB took 32 ms, nearly two frames'], 'w', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.3, ['20만 개 정렬은 262ms, 약 16프레임 동안 JS 스레드를 붙잡았어요', 'sorting 200,000 took 262 ms, holding the JS thread for about 16 frames'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['행 하나를 가공하는 데 0.74µs, 한 프레임에 약 2만 2천 행이에요', 'one row took 0.74 µs to process, about 22,000 rows per frame'], 'a', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['한 프레임에 끝나지 않는 일은 나누거나 JS 스레드 밖으로', 'split work that won’t fit in a frame, or move it off the JS thread'], 'a', 4, { w: 16.0 });
    },
    notes: [['60fps 화면은 16.7ms마다 한 프레임을 그려요 · React Native에서 터치 처리, 상태 변경, JS 애니메이션은 모두 하나의 JS 스레드에서 돌아요 · 앞에서 Hermes 0.12로 잰 작업들을 이 예산과 비교했어요', 'a 60 fps screen draws a frame every 16.7 ms, and in React Native touch handling, state changes and JS animations all run on one JS thread, so tasks measured earlier on Hermes 0.12 were compared against this budget'], ['2.1MB JSON.parse는 32ms로 거의 두 프레임이었어요 · API 응답을 한 번에 파싱하면 그동안 JS가 다른 일을 못 해요 · 눌러도 반응이 늦게 와요', 'JSON.parse of 2.1 MB took 32 ms, nearly two frames, during which JS can do nothing else after parsing an API response in one go, so presses respond late'], ['숫자 20만 개 정렬은 262ms였어요 · 약 16프레임 동안 JS 스레드가 막혀요 · 네이티브 스크롤은 계속되더라도 JS로 처리하는 터치와 애니메이션은 멈춰요', 'sorting 200,000 numbers took 262 ms, blocking the JS thread for about 16 frames, so even if native scrolling continues, touches and animations handled in JS stall'], ['행마다 필드 5개를 만드는 가공은 Hermes 0.12에서 행당 0.74µs였어요 · 한 프레임에 약 22,567행, Node의 V8은 46,388행이에요 · 큰 일은 나누거나, 서버에서 미리 하거나, 네이티브로 옮겨요', 'building 5 fields per row took 0.74 µs per row on Hermes 0.12, about 22,567 rows per frame against 46,388 on V8 in Node, so large jobs are split, done ahead on the server or moved to native']],
