    fin: [['차가운 빌드 15초', 'a cold build takes 15 s', 'rnv-xs rnv-a'], ['캐시면 0.4초', '0.4 s with the cache'], ['이상하면 캐시를 지워요', 'when in doubt, reset']],
    caps: [['Metro 캐시', 'The Metro cache'], ['차가운 빌드', 'A cold build'], ['캐시된 빌드', 'A cached build'], ['캐시 지우기', 'Resetting the cache'], ['빌드 캐시', 'Build caches']]
